sys_script_include.script:
function GetStoreAppStatus(aStoreAppWhitelist)
{
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var GetValue = x_snc_devtools.GetValue;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var Clone = x_snc_devtools.Clone;
	var IsValidSysId = x_snc_devtools.IsValidSysId;
	var IsValidAppName = x_snc_devtools.IsValidAppName;

	function IsValidScope(strScope)
	{
		return x_snc_devtools.IsSnakeCase(strScope);
	}

	aStoreAppWhitelist = GetArrayValue(aStoreAppWhitelist);

	if (aStoreAppWhitelist.length == 0)
	{
		return false;
	}

	var strQuery = '';

	if (aStoreAppWhitelist.length == 1 && GetValue(aStoreAppWhitelist,0) == 'all')
	{
		strQuery = '';
	}
	else
	{
		var aSysIds = [];
		var aScopes = [];
		var aNames = [];
		for (nStoreAppWhitelist = 0; nStoreAppWhitelist < aStoreAppWhitelist.length; nStoreAppWhitelist++)
		{
			var strStoreAppWhitelist = aStoreAppWhitelist[nStoreAppWhitelist];
			if (IsValidSysId(strStoreAppWhitelist) == true)
			{
				aSysIds.push(strStoreAppWhitelist);
			}
			else if (IsValidScope(strStoreAppWhitelist) == true)
			{
				aScopes.push(strStoreAppWhitelist);				
			}
			else if (IsValidAppName(strStoreAppWhitelist) == true)
			{
				aNames.push(strStoreAppWhitelist);
			}
			else
			{
				return false;
			}			
		}
		if (aSysIds.length > 0)
		{
			strQuery += 'sys_idIN' + GetStringValue(aSysIds);
		}	
		if (aScopes.length > 0)
		{
			if (strQuery != '')
			{
				strQuery += '^OR';
			}
			strQuery += 'scopeIN' + GetStringValue(aScopes);
		}		
		if (aNames.length > 0)
		{
			if (strQuery != '')
			{
				strQuery += '^OR';
			}
			strQuery += 'nameIN' + GetStringValue(aNames);
		}		
	}

	var aStoreApps = [];

	var grStoreApp = new GlideRecord('sys_store_app');
	grStoreApp.addEncodedQuery(strQuery);
	grStoreApp.query();
	while (grStoreApp.next())
	{
		var store_app = Clone(grStoreApp);

		delete store_app.sys_meta;
		delete store_app.sys_mod_count;
		delete store_app.sys_tags;

		aStoreApps.push(store_app);
	}

	return aStoreApps;
}
